1	// Package profile is the canonical reader for v7 benchmark profile YAML files
2	// under scripts/benchmark/profiles/. The schema is frozen by SD-010 §3
3	// (Harness × Model Matrix Benchmark); additive fields require a spec amendment.
4	package profile
5	
6	import (
7		"fmt"
8		"os"
9		"path/filepath"
10		"sort"
11		"strings"
12	
13		"gopkg.in/yaml.v3"
14	)
15	
16	// ProviderType enumerates the provider client paths supported by the
17	// matrix runner. SD-010 §3 forbids silent override; the adapter selects its
18	// client path by exact match on this field.
19	type ProviderType string
20	
21	const (
22		ProviderAnthropic    ProviderType = "anthropic"
23		ProviderOpenAI       ProviderType = "openai"
24		ProviderOpenAICompat ProviderType = "openai-compat"
25		ProviderOpenRouter   ProviderType = "openrouter"
26		ProviderOMLX         ProviderType = "omlx"
27		ProviderLMStudio     ProviderType = "lmstudio"
28		ProviderOllama       ProviderType = "ollama"
29		ProviderGoogle       ProviderType = "google"
30		ProviderRapidMLX     ProviderType = "rapid-mlx"
31		ProviderVLLM         ProviderType = "vllm"
32	)
33	
34	func (p ProviderType) valid() bool {
35		switch p {
36		case ProviderAnthropic, ProviderOpenAI, ProviderOpenAICompat, ProviderOpenRouter,
37			ProviderOMLX, ProviderLMStudio, ProviderOllama, ProviderGoogle, ProviderRapidMLX, ProviderVLLM:
38			return true
39		}
40		return false
41	}
42	
43	// Provider describes how the harness adapter should reach the model API.
44	type Provider struct {
45		Type      ProviderType `yaml:"type"`
46		Model     string       `yaml:"model"`
47		BaseURL   string       `yaml:"base_url"`
48		APIKeyEnv string       `yaml:"api_key_env"`
49	}
50	
51	// Pricing is the single source of truth for cost reconciliation. Units are
52	// USD per million tokens.
53	type Pricing struct {
54		InputUSDPerMTok       float64 `yaml:"input_usd_per_mtok"`
55		OutputUSDPerMTok      float64 `yaml:"output_usd_per_mtok"`
56		CachedInputUSDPerMTok float64 `yaml:"cached_input_usd_per_mtok"`
57	}
58	
59	// Limits captures provider-side ceilings. rate_limit_* are informational in
60	// v1 (D6 forbids concurrency > 1) and reserved for the follow-up scheduler.
61	type Limits struct {
62		MaxOutputTokens int `yaml:"max_output_tokens"`
63		ContextTokens   int `yaml:"context_tokens"`
64		RateLimitRPM    int `yaml:"rate_limit_rpm"`
65		RateLimitTPM    int `yaml:"rate_limit_tpm"`
66	}
67	
68	// Sampling is opaque to the runner; passed verbatim to the adapter's
69	// apply_profile step. Reasoning is a free-form string ("low" | "medium" |
70	// "high" | "" depending on the family). Pointer fields are omitted when
71	// nil so server defaults apply.
72	type Sampling struct {
73		Temperature float64  `yaml:"temperature"`
74		Reasoning   string   `yaml:"reasoning,omitempty"`
75		TopP        *float64 `yaml:"top_p,omitempty"`
76		TopK        *int     `yaml:"top_k,omitempty"`
77		MinP        *float64 `yaml:"min_p,omitempty"`
78	}
79	
80	// ModelServerInfo is populated at run time by querying the local model server
81	// (e.g. lmstudio /api/v0/models/<id>). Fields are empty/zero when the server
82	// does not expose them.
83	type ModelServerInfo struct {
84		Quantization        string `json:"quantization,omitempty"`
85		LoadedContextLength int    `json:"loaded_context_length,omitempty"`
86		MaxContextLength    int    `json:"max_context_length,omitempty"`
87		Source              string `json:"source,omitempty"` // URL queried
88	}
89	
90	// Versioning records when the profile was authored and which provider
91	// snapshot the adapter resolved at apply_profile time.
92	type Versioning struct {
93		ResolvedAt string `yaml:"resolved_at"`
94		Snapshot   string `yaml:"snapshot"`
95	}
96	
97	// Profile is the in-memory shape of a frozen v1 profile YAML.
98	type Profile struct {
99		ID         string     `yaml:"id"`
100		Provider   Provider   `yaml:"provider"`
101		Pricing    Pricing    `yaml:"pricing"`
102		Limits     Limits     `yaml:"limits"`
103		Sampling   Sampling   `yaml:"sampling"`
104		Versioning Versioning `yaml:"versioning"`
105	
106		// Path is the filesystem path the profile was loaded from. Not part of
107		// the YAML; populated by Load / LoadDir for diagnostics and `profiles
108		// list` output.
109		Path string `yaml:"-"`
110	}
111	
112	// Load reads and validates a single profile YAML file at path.
113	func Load(path string) (*Profile, error) {
114		raw, err := os.ReadFile(path) // #nosec G304 -- path is an operator-supplied profile location, scoped by Validate()
115		if err != nil {
116			return nil, fmt.Errorf("read profile %s: %w", path, err)
117		}
118		var p Profile
119		dec := yaml.NewDecoder(strings.NewReader(string(raw)))
120		dec.KnownFields(true)
121		if err := dec.Decode(&p); err != nil {
122			return nil, fmt.Errorf("parse profile %s: %w", path, err)
123		}
124		p.Path = path
125		if err := p.Validate(); err != nil {
126			return nil, fmt.Errorf("validate profile %s: %w", path, err)
127		}
128		return &p, nil
129	}
130	
131	// LoadDir loads every *.yaml / *.yml file under dir, sorted by id. It is the
132	// entry point used by `fiz-bench profiles list`.
133	func LoadDir(dir string) ([]*Profile, error) {
134		entries, err := os.ReadDir(dir)
135		if err != nil {
136			return nil, fmt.Errorf("read profiles dir %s: %w", dir, err)
137		}
138		var profiles []*Profile
139		for _, e := range entries {
140			if e.IsDir() {
141				continue
142			}
143			ext := strings.ToLower(filepath.Ext(e.Name()))
144			if ext != ".yaml" && ext != ".yml" {
145				continue
146			}
147			p, err := Load(filepath.Join(dir, e.Name()))
148			if err != nil {
149				return nil, err
150			}
151			profiles = append(profiles, p)
152		}
153		sort.Slice(profiles, func(i, j int) bool { return profiles[i].ID < profiles[j].ID })
154		return profiles, nil
155	}
156	
157	// Validate checks that every required v1 field is present. The schema is
158	// frozen by SD-010 §3; missing fields are a hard error rather than a warning.
159	func (p *Profile) Validate() error {
160		if strings.TrimSpace(p.ID) == "" {
161			return fmt.Errorf("id is required")
162		}
163		if !p.Provider.Type.valid() {
164			return fmt.Errorf("provider.type %q is not one of anthropic|openai|openrouter|omlx|lmstudio|ollama|google|rapid-mlx|vllm", p.Provider.Type)
165		}
166		if strings.TrimSpace(p.Provider.Model) == "" {
167			return fmt.Errorf("provider.model is required")
168		}
169		if strings.TrimSpace(p.Provider.BaseURL) == "" {
170			return fmt.Errorf("provider.base_url is required")
171		}
172		if strings.TrimSpace(p.Provider.APIKeyEnv) == "" {
173			return fmt.Errorf("provider.api_key_env is required")
174		}
175		if p.Pricing.InputUSDPerMTok < 0 || p.Pricing.OutputUSDPerMTok < 0 || p.Pricing.CachedInputUSDPerMTok < 0 {
176			return fmt.Errorf("pricing.* must be non-negative")
177		}
178		if p.Limits.MaxOutputTokens <= 0 {
179			return fmt.Errorf("limits.max_output_tokens must be > 0")
180		}
181		if p.Limits.ContextTokens <= 0 {
182			return fmt.Errorf("limits.context_tokens must be > 0")
183		}
184		if strings.TrimSpace(p.Versioning.ResolvedAt) == "" {
185			return fmt.Errorf("versioning.resolved_at is required")
186		}
187		return nil
188	}
